# Run from the workspace root; first build/save the original Legacy latency binary.
set -e
WAIT_FIX_BENCH_ROOT=worktrees/realtime-threaded-executor/tm_basic
python3 "$WAIT_FIX_BENCH_ROOT/test/executor_bench/run_latency.py" --engines legacy --baseline /tmp/legacy-wait-before --candidate "$WAIT_FIX_BENCH_ROOT/builddir_release/test/executor_bench/executor_latency_bench" --messages 2000 --sparse-messages 2000 --warmup 32 --hops 1,4,8 --repeats 3 --cpus 20,24,26,28,30,32,34,36,38 --producer-cpu 20 --consumer-cpus 24,26,28,30,32,34,36,38 --output /tmp/legacy-wait-final-latency/paired > /tmp/legacy-wait-final-latency-paired.log 2>&1
python3 "$WAIT_FIX_BENCH_ROOT/test/executor_bench/run_latency.py" --candidate-only --include-legacy --candidate "$WAIT_FIX_BENCH_ROOT/builddir_release/test/executor_bench/executor_latency_bench" --messages 2000 --sparse-messages 2000 --warmup 32 --hops 1,4,8 --spins 0,200 --repeats 3 --cpus 20,24,26,28,30,32,34,36,38 --producer-cpu 20 --consumer-cpus 24,26,28,30,32,34,36,38 --output /tmp/legacy-wait-final-latency/current > /tmp/legacy-wait-final-latency-current.log 2>&1
python3 "$WAIT_FIX_BENCH_ROOT/test/executor_bench/run_latency.py" --engines legacy --baseline /tmp/legacy-wait-before --candidate "$WAIT_FIX_BENCH_ROOT/builddir_release/test/executor_bench/executor_latency_bench" --messages 2000 --sparse-messages 2000 --warmup 32 --hops 4 --intervals 50,1000 --mode periodic --repeats 3 --cpus 20,24,26,28,30,32,34,36,38 --producer-cpu 20 --consumer-cpus 24,26,28,30,32,34,36,38 --output /tmp/legacy-wait-final-latency/periodic > /tmp/legacy-wait-final-latency-periodic.log 2>&1
python3 "$WAIT_FIX_BENCH_ROOT/test/executor_bench/run_latency.py" --engines legacy --baseline /tmp/legacy-wait-before --candidate "$WAIT_FIX_BENCH_ROOT/builddir_release/test/executor_bench/executor_latency_bench" --messages 2000 --warmup 32 --hops 8 --intervals 0 --repeats 3 --cpus 20-27 --producer-cpu 20 --consumer-cpus 24,25,26,27 --output /tmp/legacy-wait-final-latency/oversubscribed > /tmp/legacy-wait-final-latency-oversubscribed.log 2>&1
